sys_ux_data_broker_transform.script:
function transform(input) {
    var perfComm = input.perfComm;
    var progComm = input.progComm;
	var count = input.aiCallCtr;

	if (perfComm == '' || progComm == '')
		return "You don't have any Performance/Progression Comments for Dora to suggest action items.";

    var prompt = "You are an HR performance summary assistant. " +
        "Create list of actionable items based on the snapshot feedback comments recevied as per the inputs below. " +
        "Keep it professional, concise, and balanced. " +
        "If the feedback tone is negative or indicates gaps, append 1–2 improvement suggestions within the same paragraph. " +
        "If the tone is positive or neutral, do NOT add improvement suggestions. Also, you do not need to add any employee's personal info such as name, birth date, etc. " +
        "Do use bullet points but not at all any headings or paragraphs.\n\n" +
        "Performance Comments: " + perfComm + "\n" +
        "Progression Comments: " + progComm;

    var ai_resp = (count > 0) ? new global.GeminiUtils().makeCallsToGemini(prompt) : "Click on Ask Dora to get actionable items from AI.";

	return ai_resp;
}
